#ifndef MESH_CUBED_SPHERE_RAY_COLLAR_PROBE_HPP_
#define MESH_CUBED_SPHERE_RAY_COLLAR_PROBE_HPP_
#include "mesh/cubed_sphere/surface_mls_probe.hpp"
#include "mesh/cubed_sphere/scri_surface.hpp"
namespace cubed_sphere {
// Alternative standalone interpolation probe: physical-r degree5 Lagrange on
// each genuine angular donor line, followed by global 2D degree5 value MLS.
// Arbitrary Cartesian components remain independent: no spherical projection.
// It handles the angle-dependent physical radial nodes in a transition layer.
class RayCollarProbe {
 public:
 struct Term {int index;bool boundary;Real weight;};
 struct Row {std::vector<Term> terms;Real l1=0,condition=0,reproduction=0;};
 struct Angular {SurfaceMLSProbe::Row row;Real unit[3],t1[3]{},t2[3]{},scale=1;std::vector<std::array<Real,21>> basis;};
 const CompositeDifference &g;const ScriSurface &surface;const std::vector<Real>&volume,&boundary;int fields,angular_donors;
 SurfaceMLSProbe angular;
 std::vector<std::vector<Real>> radii;
 mutable std::map<std::array<Real,3>,Angular> angular_cache;
 mutable std::map<std::array<Real,4>,Row> cache;
 mutable size_t rows_built=0;mutable Real maximum_l1=0,maximum_condition=0,maximum_reproduction=0;
 RayCollarProbe(const ScriSurface&s,const std::vector<Real>&v,const std::vector<Real>&b,int f,int donors=48):g(s.grid),surface(s),volume(v),boundary(b),fields(f),angular_donors(donors),angular(g.mesh,1,donors),radii(s.rows.size(),std::vector<Real>(g.n+1)){if(v.size()!=size_t(g.count*f)||b.size()!=s.rows.size()*f)throw std::invalid_argument("ray collar layout");for(size_t p=0;p<s.rows.size();++p){const auto &row=s.rows[p];for(int i=0;i<g.n;++i){Real q[3]={(i+.5)/g.n,(row.j+.5)/g.n,(row.k+.5)/g.n},x[3];g.mesh.Forward(row.block,q,x);Real r=0;for(Real a:x)r+=a*a;radii[p][i]=std::sqrt(r);}radii[p][g.n]=g.mesh.radii.back();}}
 Angular BuildAngular(int block,const Real*q)const{Angular out;Real at[3]={1,q[1],q[2]},x[3];g.mesh.Forward(block,at,x);Real radius=0;for(Real a:x)radius+=a*a;radius=std::sqrt(radius);for(int i=0;i<3;++i)out.unit[i]=x[i]/radius;out.row=angular.Build(out.unit);int axis=0;for(int a=1;a<3;++a)if(std::abs(out.unit[a])<std::abs(out.unit[axis]))axis=a;out.t1[axis]=1;Real norm=0;for(int a=0;a<3;++a){out.t1[a]-=out.unit[axis]*out.unit[a];norm+=out.t1[a]*out.t1[a];}for(Real &a:out.t1)a/=std::sqrt(norm);for(int a=0;a<3;++a)out.t2[a]=out.unit[(a+1)%3]*out.t1[(a+2)%3]-out.unit[(a+2)%3]*out.t1[(a+1)%3];if(out.row.ids.size()>1){out.scale=0;for(int id:out.row.ids){Real d=0;for(int a=0;a<3;++a)d+=std::pow(angular.points[id][a]-out.unit[a],2);out.scale=std::max(out.scale,std::sqrt(d));}}
  for(int id:out.row.ids){const auto &node=angular.points[id];Real dot=0,u=0,v=0;for(int a=0;a<3;++a){dot+=node[a]*out.unit[a];u+=node[a]*out.t1[a];v+=node[a]*out.t2[a];}u/=dot*out.scale;v/=dot*out.scale;std::array<Real,21>b;int k=0;for(int degree=0;degree<=5;++degree)for(int a=0;a<=degree;++a)b[k++]=std::pow(u,a)*std::pow(v,degree-a);out.basis.push_back(b);}return out;
 }
 static Real VandermondeCondition(const std::vector<Real>&z){const int n=z.size();Real a[8][8]{},inverse[8][8]{},norm=0;for(int i=0;i<n;++i){Real sum=0;for(int k=0;k<n;++k){a[i][k]=std::pow(z[i],k);sum+=std::abs(a[i][k]);}norm=std::max(norm,sum);inverse[i][i]=1;}for(int k=0;k<n;++k){int pivot=k;for(int i=k+1;i<n;++i)if(std::abs(a[i][k])>std::abs(a[pivot][k]))pivot=i;if(std::abs(a[pivot][k])<1e-12)throw std::runtime_error("ray radial rank guard");for(int j=0;j<n;++j){std::swap(a[k][j],a[pivot][j]);std::swap(inverse[k][j],inverse[pivot][j]);}const Real scale=a[k][k];for(int j=0;j<n;++j){a[k][j]/=scale;inverse[k][j]/=scale;}for(int i=0;i<n;++i)if(i!=k){Real c=a[i][k];for(int j=0;j<n;++j){a[i][j]-=c*a[k][j];inverse[i][j]-=c*inverse[k][j];}}}Real invnorm=0;for(int i=0;i<n;++i){Real sum=0;for(int j=0;j<n;++j)sum+=std::abs(inverse[i][j]);invnorm=std::max(invnorm,sum);}return norm*invnorm;}
 Row Build(const Angular&a,int block,const Real*q)const{Real x[3];g.mesh.Forward(block,q,x);Real radius=0;for(Real z:x)radius+=z*z;radius=q[0]==1?g.mesh.radii.back():std::sqrt(radius);const int owner=g.mesh.Owner(x);if(owner<0||surface.base[owner]<0)throw std::runtime_error("ray query outside collar");Real local[3];g.mesh.Inverse(owner,x,local);const auto geometry=g.mesh.Geometry(owner,local);Real invh=0;for(int i=0;i<3;++i)invh+=g.n*geometry.J[0][i]*x[i]/radius;if(!(invh>0))throw std::runtime_error("ray query normal spacing");const int n=surface.radial_nodes;Row out;Real radial_condition_max=1;out.condition=a.row.condition;std::vector<std::array<Real,8>> radial_reproduction;
  for(size_t line=0;line<a.row.ids.size();++line){const int id=a.row.ids[line];std::vector<std::pair<Real,int>> nearest;for(int i=0;i<=g.n;++i)nearest.push_back({std::abs(radii[id][i]-radius),i});std::partial_sort(nearest.begin(),nearest.begin()+n,nearest.end());std::vector<Real> nodes,weights(n),scaled;for(int i=0;i<n;++i)nodes.push_back(radii[id][nearest[i].second]);Real scale=0;for(Real r:nodes)scale=std::max(scale,std::abs(r-radius));if(!(scale>0))throw std::runtime_error("ray radial scale");for(Real r:nodes)scaled.push_back((r-radius)/scale);radial_condition_max=std::max(radial_condition_max,VandermondeCondition(scaled));out.condition=a.row.condition*radial_condition_max;if(out.condition>=1e8)throw std::runtime_error("ray condition guard");std::array<Real,8> reproduced{};
   for(int i=0;i<n;++i){weights[i]=1;for(int j=0;j<n;++j)if(i!=j)weights[i]*=(radius-nodes[j])/(nodes[i]-nodes[j]);const Real weight=a.row.weights[line]*weights[i];const auto&row=surface.rows[id];const int normal=nearest[i].second;out.terms.push_back({normal==g.n?id:g.Index(row.block,normal,row.j,row.k),normal==g.n,weight});out.l1+=std::abs(weight);for(int k=0;k<n;++k)reproduced[k]+=weights[i]*std::pow((nodes[i]-radius)*invh,k);}radial_reproduction.push_back(reproduced);
  }
  if(!(out.l1<=8&&std::isfinite(out.l1)))throw std::runtime_error("ray value L1 guard: "+std::to_string(out.l1));for(int k=0;k<n;++k)for(int p=0;p<21;++p){Real value=0;for(size_t l=0;l<a.row.ids.size();++l)value+=a.row.weights[l]*a.basis[l][p]*radial_reproduction[l][k];out.reproduction=std::max(out.reproduction,std::abs(value-(k==0&&p==0?1.:0)));}if(!(out.reproduction<1e-10))throw std::runtime_error("ray tensor polynomial reproduction guard: "+std::to_string(out.reproduction));++rows_built;maximum_l1=std::max(maximum_l1,out.l1);maximum_condition=std::max(maximum_condition,out.condition);maximum_reproduction=std::max(maximum_reproduction,out.reproduction);return out;
 }
 std::vector<Real> Sample(int block,const Real*q)const{std::array<Real,4> key{Real(block),q[0],q[1],q[2]};for(int a=0;a<3;++a){Real lattice=std::round(2*g.n*q[a]);if(std::abs(2*g.n*q[a]-lattice)<1e-12)key[a+1]=lattice/(2*g.n);}auto found=cache.find(key);if(found==cache.end()){std::array<Real,3>direction{Real(block),key[2],key[3]};auto angular=angular_cache.find(direction);if(angular==angular_cache.end())angular=angular_cache.emplace(direction,BuildAngular(block,q)).first;found=cache.emplace(key,Build(angular->second,block,q)).first;}const auto &row=found->second;auto value=[&](const Term&t,int f){return t.boundary?boundary[t.index*fields+f]:volume[f*g.count+t.index];};std::vector<Real> out(fields);for(int f=0;f<fields;++f){const Real anchor=value(row.terms[0],f);out[f]=anchor;for(const auto&t:row.terms)out[f]+=t.weight*(value(t,f)-anchor);}return out;}
};
} // namespace cubed_sphere
#endif
